<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pharmacy Operations | HMS</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css">
    <style>
        :root{--bg:#091b35;--panel:#122b50;--raised:#1b3964;--line:#2c4770;--gold:#edbd3f;--muted:#bdc8db;--green:#75dda6;--red:#ef9297}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#fff;font:14px 'DM Sans',sans-serif}.wrap{max-width:1450px;margin:auto;padding:24px 26px 45px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}h1,h2{font-family:Manrope,sans-serif}h1{margin:0;font-size:29px}h2{margin:0;font-size:15px}.subtitle{margin:6px 0;color:var(--muted)}.back,.button{border:1px solid var(--line);border-radius:8px;padding:10px 14px;color:#fff;text-decoration:none;background:var(--panel);font-weight:700}.back{color:var(--gold)}.button.primary,button{background:var(--gold);color:#12284a;border-color:var(--gold)}.banner{margin-bottom:15px;padding:12px 15px;border:1px solid var(--gold);border-radius:8px;color:var(--gold);background:#2d2715}.error{border-color:var(--red);color:#ffd8da;background:#40232a}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.kpi,.card{border:1px solid var(--line);border-radius:10px;background:var(--panel)}.kpi{padding:16px}.kpi small{color:var(--muted)}.kpi strong{display:block;margin-top:7px;color:var(--gold);font:800 25px Manrope,sans-serif}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.grid.wide{grid-template-columns:1.3fr .7fr}.card{overflow:hidden}.head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 16px;border-bottom:1px solid var(--line)}.head i{color:var(--gold);margin-right:8px}.body{padding:16px}.note{color:var(--muted);font-size:12px;margin:0 0 13px}form label{display:grid;gap:6px;margin-bottom:11px;color:var(--muted);font-size:12px}input,select,textarea{width:100%;min-height:39px;padding:8px 10px;border:1px solid #466387;border-radius:7px;background:#0c2446;color:#fff;font:inherit}textarea{min-height:62px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:11px}button{min-height:39px;padding:0 13px;border:0;border-radius:7px;font-weight:800;cursor:pointer}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px;font-size:12px}th,td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{background:var(--raised);color:var(--gold);font-size:11px}td small{color:var(--muted)}.badge{display:inline-flex;padding:4px 8px;border-radius:999px;background:var(--gold);color:#10284b;font-size:10px;font-weight:800}.badge.low{background:var(--red);color:#fff}.badge.green{background:var(--green);color:#103a2a}.empty{text-align:center;color:var(--muted);padding:20px}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:12px}.tabs a{padding:8px 11px;border:1px solid var(--line);border-radius:7px;color:var(--muted);text-decoration:none}.tabs a:hover{color:var(--gold);border-color:var(--gold)}.section{scroll-margin-top:18px}.money{color:#f7d676;font-weight:700}@media(max-width:1000px){.grid,.grid.wide{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){.wrap{padding:16px 12px}.top{align-items:flex-start;flex-direction:column}.kpis{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}}
    </style>
<style>
        html { scrollbar-width: thin; scrollbar-color: var(--gold) var(--bg); scroll-behavior: smooth; }
        ::-webkit-scrollbar { width: 10px; height: 10px; }
        ::-webkit-scrollbar-track { background: var(--bg); }
        ::-webkit-scrollbar-thumb { background: var(--gold); border: 2px solid var(--bg); border-radius: 999px; }
        ::-webkit-scrollbar-thumb:hover { background: var(--gold); }
        ::-webkit-scrollbar-corner { background: var(--bg); }
        .table { scrollbar-width: thin; scrollbar-color: var(--gold) var(--bg); }
    </style>
</head>
<body><main class="wrap">
    <header class="top"><div><h1><i class="fa-solid fa-pills" style="color:var(--gold)"></i> Pharmacy Operations</h1><p class="subtitle">Inventory, purchases, sales, prescriptions, returns, suppliers, staff and pharmacy reports.</p></div><a class="back" href="{{ url('/') }}"><i class="fa-solid fa-arrow-left"></i> Dashboard</a></header>
    @if(session('status'))<div class="banner"><i class="fa-solid fa-circle-check"></i> {{ session('status') }}</div>@endif
    @if($errors->any())<div class="banner error"><i class="fa-solid fa-triangle-exclamation"></i> {{ $errors->first() }}</div>@endif
    <nav class="tabs"><a href="#inventory">Medicines &amp; Inventory</a><a href="#purchases">Purchases</a><a href="#sales">Sales</a><a href="#prescriptions">Prescriptions</a><a href="#returns">Returns</a><a href="#suppliers">Suppliers</a><a href="#staff">Pharmacy Staff</a><a href="#reports">Reports</a></nav>
    <section class="kpis"><div class="kpi"><small>Total medicines</small><strong>{{ $kpis['medicines'] }}</strong></div><div class="kpi"><small>Low stock items</small><strong>{{ $kpis['low_stock'] }}</strong></div><div class="kpi"><small>Sales today</small><strong>Rs {{ number_format($kpis['sales_today'],0) }}</strong></div><div class="kpi"><small>Prescriptions today</small><strong>{{ $kpis['prescriptions_today'] }}</strong></div></section>

    <section class="grid section" id="inventory"><article class="card"><div class="head"><h2><i class="fa-solid fa-boxes-stacked"></i>Medicine inventory</h2><span class="badge">Live stock</span></div><div class="body"><p class="note">Register medicines and control their low-stock thresholds.</p><form method="POST" action="{{ route('pharmacy.medicines.store') }}">@csrf<div class="row"><label>Medicine name<input name="name" placeholder="Paracetamol 500mg" required></label><label>Unit<input name="unit" placeholder="Tablet / Vial" required></label></div><div class="row"><label>Opening stock<input type="number" name="stock" min="0" required></label><label>Low-stock threshold<input type="number" name="low_stock_threshold" min="0" value="20" required></label></div><button><i class="fa-solid fa-plus"></i> Add medicine</button></form></div><div class="table"><table><thead><tr><th>Medicine</th><th>Unit</th><th>Stock</th><th>Threshold</th><th>Status</th></tr></thead><tbody>@forelse($medicines as $medicine)<tr><td>{{ $medicine->name }}</td><td>{{ $medicine->unit }}</td><td>{{ $medicine->stock }}</td><td>{{ $medicine->low_stock_threshold }}</td><td><span class="badge {{ $medicine->stock <= $medicine->low_stock_threshold ? 'low' : 'green' }}">{{ $medicine->stock <= $medicine->low_stock_threshold ? 'Low stock' : 'Healthy' }}</span></td></tr>@empty<tr><td colspan="5" class="empty">No medicines added yet.</td></tr>@endforelse</tbody></table></div></article>
        <article class="card section" id="suppliers"><div class="head"><h2><i class="fa-solid fa-truck"></i>Suppliers</h2><span class="badge">{{ $suppliers->count() }} registered</span></div><div class="body"><p class="note">Add approved suppliers and payment terms for purchasing.</p><form method="POST" action="{{ route('pharmacy.suppliers.store') }}">@csrf<div class="row"><label>Supplier name<input name="name" placeholder="MedSupply Pakistan" required></label><label>Contact person<input name="contact_person" placeholder="Account manager"></label></div><div class="row"><label>Phone<input name="phone"></label><label>Email<input type="email" name="email"></label></div><label>Payment terms<input name="payment_terms" placeholder="30 days credit"></label><button><i class="fa-solid fa-user-plus"></i> Add supplier</button></form></div><div class="table"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Terms</th><th>Status</th></tr></thead><tbody>@forelse($suppliers as $supplier)<tr><td>{{ $supplier->name }}</td><td>{{ $supplier->contact_person ?: $supplier->phone ?: '—' }}</td><td>{{ $supplier->payment_terms ?: '—' }}</td><td><span class="badge green">{{ $supplier->status }}</span></td></tr>@empty<tr><td colspan="4" class="empty">No suppliers added yet.</td></tr>@endforelse</tbody></table></div></article></section>

    <section class="grid section" id="purchases"><article class="card"><div class="head"><h2><i class="fa-solid fa-cart-shopping"></i>Purchase &amp; stock receiving</h2></div><div class="body"><p class="note">Receiving a purchase automatically increases medicine stock.</p><form method="POST" action="{{ route('pharmacy.purchases.store') }}">@csrf<label>Supplier<select name="supplier_id" required><option value="">Select supplier</option>@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}">{{ $supplier->name }}</option>@endforeach</select></label><div class="row"><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option>@foreach($medicines as $medicine)<option value="{{ $medicine->id }}">{{ $medicine->name }} ({{ $medicine->stock }} {{ $medicine->unit }})</option>@endforeach</select></label><label>Quantity<input type="number" name="quantity" min="1" required></label></div><div class="row"><label>Unit cost<input type="number" name="unit_cost" min="0" step="0.01" required></label><label>Batch number<input name="batch_number"></label></div><label>Expiry date<input type="date" name="expiry_date"></label><button><i class="fa-solid fa-box-open"></i> Receive purchase</button></form></div></article><article class="card"><div class="head"><h2><i class="fa-solid fa-file-invoice"></i>Purchase history</h2></div><div class="table"><table><thead><tr><th>PO</th><th>Supplier</th><th>Total</th><th>Date</th></tr></thead><tbody>@forelse($purchases as $purchase)<tr><td>{{ $purchase->purchase_number }}</td><td>{{ $purchase->supplier->name }}</td><td class="money">Rs {{ number_format($purchase->total_amount,0) }}</td><td>{{ $purchase->purchase_date->format('d M Y') }}</td></tr>@empty<tr><td colspan="4" class="empty">No purchases recorded.</td></tr>@endforelse</tbody></table></div></article></section>

    <section class="grid section" id="sales"><article class="card"><div class="head"><h2><i class="fa-solid fa-cash-register"></i>Medicine sale</h2></div><div class="body"><p class="note">Sale validates stock and reduces inventory automatically.</p><form method="POST" action="{{ route('pharmacy.sales.store') }}">@csrf<label>Patient (optional)<select name="patient_id"><option value="">Walk-in patient</option>@foreach($patients as $patient)<option value="{{ $patient->id }}">{{ $patient->patient_code }} · {{ $patient->name }}</option>@endforeach</select></label><div class="row"><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option>@foreach($medicines as $medicine)<option value="{{ $medicine->id }}">{{ $medicine->name }} · {{ $medicine->stock }} available</option>@endforeach</select></label><label>Quantity<input type="number" name="quantity" min="1" required></label></div><div class="row"><label>Unit price<input type="number" name="unit_price" min="0" step="0.01" required></label><label>Payment method<select name="payment_method"><option>Cash</option><option>Card</option><option>Insurance</option><option>Credit</option></select></label></div><button><i class="fa-solid fa-receipt"></i> Complete sale</button></form></div></article><article class="card"><div class="head"><h2><i class="fa-solid fa-receipt"></i>Recent sales</h2></div><div class="table"><table><thead><tr><th>Sale</th><th>Patient</th><th>Items</th><th>Total</th><th>Payment</th></tr></thead><tbody>@forelse($sales as $sale)<tr><td>{{ $sale->sale_number }}</td><td>{{ $sale->patient->name ?? 'Walk-in' }}</td><td>{{ $sale->items->first()->medicine->name ?? '—' }} × {{ $sale->items->sum('quantity') }}</td><td class="money">Rs {{ number_format($sale->total_amount,0) }}</td><td>{{ $sale->payment_method }}</td></tr>@empty<tr><td colspan="5" class="empty">No sales recorded.</td></tr>@endforelse</tbody></table></div></article></section>

    <section class="grid section" id="prescriptions"><article class="card"><div class="head"><h2><i class="fa-solid fa-file-prescription"></i>Prescription queue</h2></div><div class="body"><p class="note">Create a doctor prescription with dosage and duration for pharmacy processing.</p><form method="POST" action="{{ route('pharmacy.prescriptions.store') }}">@csrf<div class="row"><label>Patient<select name="patient_id" required><option value="">Select patient</option>@foreach($patients as $patient)<option value="{{ $patient->id }}">{{ $patient->patient_code }} · {{ $patient->name }}</option>@endforeach</select></label><label>Doctor<select name="doctor_id" required><option value="">Select doctor</option>@foreach($doctors as $doctor)<option value="{{ $doctor->id }}">{{ $doctor->name }}</option>@endforeach</select></label></div><div class="row"><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option>@foreach($medicines as $medicine)<option value="{{ $medicine->id }}">{{ $medicine->name }}</option>@endforeach</select></label><label>Quantity<input type="number" name="quantity" min="1" required></label></div><div class="row"><label>Dosage<input name="dosage" placeholder="1 tablet twice daily"></label><label>Duration<input name="duration" placeholder="5 days"></label></div><button><i class="fa-solid fa-paper-plane"></i> Add prescription</button></form></div></article><article class="card"><div class="head"><h2><i class="fa-solid fa-clock"></i>Prescription history</h2></div><div class="table"><table><thead><tr><th>Code</th><th>Patient</th><th>Doctor</th><th>Medicine</th><th>Status</th></tr></thead><tbody>@forelse($prescriptions as $prescription)<tr><td>{{ $prescription->code }}</td><td>{{ $prescription->patient->name }}</td><td>{{ $prescription->doctor->name }}</td><td>{{ $prescription->items->first()->medicine->name ?? '—' }}</td><td><span class="badge">{{ $prescription->status }}</span></td></tr>@empty<tr><td colspan="5" class="empty">No prescriptions in queue.</td></tr>@endforelse</tbody></table></div></article></section>

    <section class="grid section" id="returns"><article class="card"><div class="head"><h2><i class="fa-solid fa-rotate-left"></i>Returns &amp; refunds</h2></div><div class="body"><p class="note">Returned stock is restored automatically and refund details are retained.</p><form method="POST" action="{{ route('pharmacy.returns.store') }}">@csrf<div class="row"><label>Medicine<select name="medicine_id" required><option value="">Select medicine</option>@foreach($medicines as $medicine)<option value="{{ $medicine->id }}">{{ $medicine->name }}</option>@endforeach</select></label><label>Patient<select name="patient_id"><option value="">Walk-in</option>@foreach($patients as $patient)<option value="{{ $patient->id }}">{{ $patient->name }}</option>@endforeach</select></label></div><div class="row"><label>Quantity<input type="number" name="quantity" min="1" required></label><label>Refund amount<input type="number" name="refund_amount" min="0" step="0.01" required></label></div><label>Reason<input name="reason" placeholder="Damaged pack / wrong medicine" required></label><label>Processed by<input name="processed_by" placeholder="Pharmacy staff name" required></label><button><i class="fa-solid fa-arrow-rotate-left"></i> Process return</button></form></div></article><article class="card"><div class="head"><h2><i class="fa-solid fa-list"></i>Return log</h2></div><div class="table"><table><thead><tr><th>Return</th><th>Medicine</th><th>Qty</th><th>Refund</th><th>Reason</th></tr></thead><tbody>@forelse($returns as $return)<tr><td>{{ $return->return_number }}</td><td>{{ $return->medicine->name }}</td><td>{{ $return->quantity }}</td><td class="money">Rs {{ number_format($return->refund_amount,0) }}</td><td>{{ $return->reason }}</td></tr>@empty<tr><td colspan="5" class="empty">No returns recorded.</td></tr>@endforelse</tbody></table></div></article></section>

    <section class="grid wide section" id="staff"><article class="card"><div class="head"><h2><i class="fa-solid fa-users-gear"></i>Pharmacy staff management</h2><span class="badge">Add staff</span></div><div class="body"><p class="note">Button-based staff setup with counter and responsibility assignment.</p><form method="POST" action="{{ route('pharmacy.staff.store') }}">@csrf<div class="row"><label>Name<input name="name" placeholder="Ayesha Khan" required></label><label>Role<input name="role" placeholder="Pharmacist / Cashier" required></label></div><div class="row"><label>Shift<select name="shift"><option>Morning</option><option>Evening</option><option>Night</option></select></label><label>Counter<input name="counter" placeholder="Counter 1"></label></div><label>Responsibility<input name="responsibility" placeholder="Prescription verification and dispensing" required></label><button><i class="fa-solid fa-user-plus"></i> Add pharmacy staff</button></form></div><div class="table"><table><thead><tr><th>Staff</th><th>Role / Shift</th><th>Responsibility</th><th>Counter</th><th>Status</th></tr></thead><tbody>@forelse($staff as $member)<tr><td>{{ $member->name }}</td><td>{{ $member->role }}<br><small>{{ $member->shift }}</small></td><td>{{ $member->pharmacyAssignments->first()->responsibility ?? '—' }}</td><td>{{ $member->pharmacyAssignments->first()->counter ?? '—' }}</td><td><span class="badge green">{{ $member->status }}</span></td></tr>@empty<tr><td colspan="5" class="empty">No pharmacy staff added.</td></tr>@endforelse</tbody></table></div></article><article class="card section" id="reports"><div class="head"><h2><i class="fa-solid fa-chart-line"></i>Pharmacy reports</h2></div><div class="body"><p class="note">Live operational indicators from stored pharmacy transactions.</p><div class="kpi"><small>Inventory value proxy</small><strong>Rs {{ number_format($medicines->sum(fn($medicine) => $medicine->stock),0) }} units</strong></div><br><div class="kpi"><small>Suppliers</small><strong>{{ $suppliers->count() }}</strong></div><br><div class="kpi"><small>Returns logged</small><strong>{{ $returns->count() }}</strong></div></div></article></section>
</main></body></html>